                {'id': 8, 'text': '第一千年紀の問題その一。', 'image': '画像のファイルパス', 'choices': [{'id': 1, 'text': '選択肢その一'}, {'id': 2, 'text': '選択肢その二'}, {'id': 3, 'text': '選択肢その三'}, {'id': 4, 'text': '選択肢その四'}], 'correct_choice_id': 1, 'explanation': '<br>一千年紀の問題一の解説。', 'category': ''}, 
                
